34		submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a2", DeviceID: "dev-1", Value: rawInt(8)})
35	
36		before, err := s.GetCRDTSnapshot("doc")
37		if err != nil {
38			t.Fatal(err)
39		}
40		if before.Operations != 3 || before.Tombstones != 0 {
41			t.Fatalf("before compaction: operations=%d tombstones=%d, want 3/0", before.Operations, before.Tombstones)
42		}
43		if string(before.Value) != "11" {
44			t.Fatalf("before compaction: value = %s, want 11", before.Value)
45		}
46	
47		snapshot, err := s.CompactCRDT("doc", "dev-1")
48		if err != nil {
49			t.Fatal(err)
50		}
51		if snapshot.Operations != 2 || snapshot.Tombstones != 0 {
52			t.Fatalf("after compaction: operations=%d tombstones=%d, want 2/0", snapshot.Operations, snapshot.Tombstones)
53		}
54		if snapshot.Type != CRDTTypeCounter || string(snapshot.Value) != "11" {
55			t.Fatalf("after compaction: %s %s, want counter 11", snapshot.Type, snapshot.Value)
56		}
57		// The merged state read is untouched by the trim.
58		if got := crdtStateValue(t, s, "doc"); got != "11" {
59			t.Fatalf("state after compaction = %s, want 11", got)
60		}
61	
62		// A repeat compaction trims nothing and reports the same snapshot.
63		again, err := s.CompactCRDT("doc", "dev-1")
64		if err != nil {
65			t.Fatal(err)
66		}
67		if again.Type != snapshot.Type || string(again.Value) != string(snapshot.Value) ||
68			again.Operations != snapshot.Operations || again.Tombstones != snapshot.Tombstones {
69			t.Fatalf("re-compaction = %+v, want %+v", again, snapshot)
70		}
71	
72		// The regression gate still uses the retained per-device maximum.
73		_, err = s.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
74			{ID: "a3", DeviceID: "dev-1", Value: rawInt(7)},
75		})
76		var conflict *ErrCRDTConflict
77		if !errors.As(err, &conflict) {
78			t.Fatalf("regression after compaction err = %v, want *ErrCRDTConflict", err)
79		}
80		// The retained op stays idempotent; a new advance still lands.
81		results, err := s.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
82			{ID: "a2", DeviceID: "dev-1", Value: rawInt(8)},
83		})
