// Accepted-operation identities keep idempotency and conflict decisions
// working after compaction. Compaction trims the rows a merge derives its
// result from — superseded counter contributions, covered gset operations,
// older register versions, dead orset tags and their tombstones — but a
// re-submitted operation id must still be recognized. For every id ever
// accepted this table retains exactly what that decision compares: the
// originating device and a digest of the type-specific comparison content.
//
// The table never participates in a merge: the counter sum, the set union,
// the register winner and the live orset tags are all derived without it. It
// stores a fixed-size digest rather than the operation payload, so retaining
// it cannot grow the trimmed state back toward its pre-compaction footprint.

package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"errors"
	"sort"
)

// canonicalOpDigest renders the type-specific comparison content of op in a
// single canonical form and hashes it, prefixed by the type so contents of
// different types never collide. A re-submission of the same id carries the
// same digest exactly when the submission layer's existing equality rules
// accept it as idempotent:
//
//   - counter: the decoded non-negative integer (client formatting ignored);
//   - gset: the element set (order and duplicates ignored, as in
//     stringSetEqual), rendered as a sorted unique JSON array;
//   - register: the version together with the JSON-semantic value (1 and 1.0
//     and reordered object keys compare equal, as in jsonEqual);
//   - orset: the action and the element.
func canonicalOpDigest(docType string, op CRDTOp) ([]byte, error) {
	var content []byte
	switch docType {
	case CRDTTypeCounter:
		n, err := decodeCounterValue(op.Value)
		if err != nil {
			return nil, err
		}
		content, err = json.Marshal(n)
		if err != nil {
			return nil, err
		}
	case CRDTTypeGSet:
		set := make(map[string]struct{}, len(op.Elements))
		for _, element := range op.Elements {
			set[element] = struct{}{}
		}
		elements := make([]string, 0, len(set))
		for element := range set {
			elements = append(elements, element)
		}
		sort.Strings(elements)
		raw, err := json.Marshal(elements)
		if err != nil {
			return nil, err
		}
		content = raw
	case CRDTTypeRegister:
		if op.Version < 0 {
			return nil, errors.New("register version must be a non-negative integer")
		}
		var value any
		if err := json.Unmarshal(op.Value, &value); err != nil {
			return nil, err
		}
		// Re-marshaling the decoded value canonicalizes whitespace and object
		// key order exactly the way jsonEqual compares values.
		normalized, err := json.Marshal(value)
		if err != nil {
			return nil, err
		}
		content = []byte(`{"version":`)
		content = strconvAppendInt(content, op.Version)
		content = append(content, []byte(`,"value":`)...)
		content = append(content, normalized...)
		content = append(content, '}')
	case CRDTTypeORSet:
		if op.Action != CRDTORSetAdd && op.Action != CRDTORSetRemove {
			return nil, errors.New(`orset action must be "add" or "remove"`)
		}
		content = []byte(encodeORSetContent(op.Action, op.Element))
	default:
		return nil, errors.New("unknown crdt type")
	}

	h := sha256.New()
	_, _ = h.Write([]byte(docType))
	_, _ = h.Write([]byte{0})
	_, _ = h.Write(content)
	return h.Sum(nil), nil
}

// strconvAppendInt appends n to b in decimal without importing strconv at the
// call site; register versions are non-negative int64s.
func strconvAppendInt(b []byte, n int64) []byte {
	if n == 0 {
		return append(b, '0')
	}
	var digits [20]byte
	i := len(digits)
	for n > 0 {
		i--
		digits[i] = byte('0' + n%10)
		n /= 10
	}
	return append(b, digits[i:]...)
}

// lookupCRDTOpIdentity returns the retained device and content digest for a
// previously accepted operation id. found is false when the id was never
// accepted.
func lookupCRDTOpIdentity(q interface {
	QueryRow(query string, args ...any) *sql.Row
}, documentID, id string) (deviceID string, digest []byte, found bool, err error) {
	err = q.QueryRow(
		`SELECT device_id, digest FROM crdt_op_identities WHERE document_id = ? AND id = ?`,
		documentID, id,
	).Scan(&deviceID, &digest)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", nil, false, nil
	case err != nil:
		return "", nil, false, err
	default:
		return deviceID, digest, true, nil
	}
}

// insertCRDTOpIdentity retains the identity of a newly accepted operation id.
// The caller has already established (in the same transaction) that the id was
// never accepted, so the primary-key insert always lands.
func insertCRDTOpIdentity(tx *sql.Tx, documentID string, op CRDTOp, digest []byte) error {
	_, err := tx.Exec(
		`INSERT INTO crdt_op_identities (document_id, id, device_id, digest) VALUES (?, ?, ?, ?)`,
		documentID, op.ID, op.DeviceID, digest,
	)
	return err
}

