		if err != nil {
			return false, &ErrCRDTConflict{ID: op.ID, Reason: err.Error()}
		}
		digest, err := canonicalOpDigest(CRDTTypeCounter, op)
		if err != nil {
			return false, &ErrCRDTConflict{ID: op.ID, Reason: err.Error()}
		}

		// The identity record survives compaction, so an id whose contribution
		// row was trimmed is still recognized: the same device and value replay
		// idempotently, a different device or value is a conflict, regardless
		// of what the trimmed merge tables now hold.
		if existingDevice, existingDigest, found, err := lookupCRDTOpIdentity(tx, documentID, op.ID); err != nil {
			return false, err
		} else if found {
			if existingDevice != op.DeviceID || !bytes.Equal(existingDigest, digest) {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device or value",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
			continue
		}

		// New id: enforce monotonicity against this device's maximum.
