// equalDigest compares two SHA-256 digests without importing bytes into the
// submission path.
func equalDigest(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// retainCRDTOpIdentity moves the comparable identity (device plus content
// digest) of one operation row compaction is about to drop into
// crdt_op_identities. The id is absent from the identity table at that point,
// so the insert always lands.
